CREATE TABLE IF NOT EXISTS public.documents (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES public.families(id) ON DELETE CASCADE, title TEXT NOT NULL, kind TEXT NOT NULL, file_name TEXT NOT NULL, mime_type TEXT NOT NULL, storage_path TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', summary TEXT NOT NULL DEFAULT '', extracted_text TEXT NOT NULL DEFAULT '', error TEXT);
CREATE TABLE IF NOT EXISTS public.document_people (document_id TEXT NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, person_id TEXT NOT NULL REFERENCES public.people(id) ON DELETE CASCADE, PRIMARY KEY(document_id,person_id));
CREATE TABLE IF NOT EXISTS public.document_claims (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, person_id TEXT REFERENCES public.people(id) ON DELETE SET NULL, quote TEXT NOT NULL, statement TEXT NOT NULL, certainty TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public.document_relationships (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, family_id TEXT NOT NULL REFERENCES public.families(id) ON DELETE CASCADE, person_a TEXT NOT NULL REFERENCES public.people(id) ON DELETE CASCADE, person_b TEXT NOT NULL REFERENCES public.people(id) ON DELETE CASCADE, type TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES public.document_claims(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.document_events (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, description TEXT NOT NULL, type TEXT NOT NULL, year INTEGER, place TEXT, certainty TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public.document_event_people (event_id TEXT NOT NULL REFERENCES public.document_events(id) ON DELETE CASCADE, person_id TEXT NOT NULL REFERENCES public.people(id) ON DELETE CASCADE, PRIMARY KEY(event_id,person_id));
CREATE TABLE IF NOT EXISTS public.document_event_claims (event_id TEXT NOT NULL REFERENCES public.document_events(id) ON DELETE CASCADE, claim_id TEXT NOT NULL REFERENCES public.document_claims(id) ON DELETE CASCADE, PRIMARY KEY(event_id,claim_id));
CREATE TABLE IF NOT EXISTS public.document_processing_jobs (id TEXT PRIMARY KEY, document_id TEXT NOT NULL UNIQUE REFERENCES public.documents(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, lease_until TEXT, error TEXT);
CREATE INDEX IF NOT EXISTS documents_family ON public.documents(family_id,created_at);
CREATE INDEX IF NOT EXISTS document_jobs_pending ON public.document_processing_jobs(status,available_at);
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_people ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_relationships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_event_people ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_event_claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_processing_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.documents, public.document_people, public.document_claims, public.document_relationships, public.document_events, public.document_event_people, public.document_event_claims, public.document_processing_jobs FROM anon, authenticated;
